            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "One voice, speaking truth is a greater force than fleets and armies, given time; plenty of time.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "When action grows unprofitable, gather information; when information grows unprofitable, sleep.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "The only thing that makes life possible is permanent, intolerable uncertainty: not knowing what comes next.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "If civilization has an opposite, it is war.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "Elegance is a small price to pay for enlightenment, and I was glad to pay it.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "To oppose something is to maintain it. You must go somewhere else; you must have another goal; then you walk a different road.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "To learn which questions are unanswerable, and not to answer them: this skill is most needful in times of stress and darkness.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "It is not human to be without shame and without desire.", Author = "Ursula K. Le Guin" },
