            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "It is good to have an end to journey towards; but it is the journey that matters, in the end.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "Light is the left hand of darkness and darkness the right hand of light. Two are one, life and death, lying together like lovers in kemmer, like hands joined together, like the end and the way.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "A profound love between two people involves, after all, the power and chance of doing profound hurt.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "Wrongs done could not be righted, but at least they were not still being done.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "What are they doing? abruptly becomes, What are we doing? and then, What must I do?", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "What is, is. There is no use pretending, now, that we do not know how to kill one another.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "It is of the nature of idea to be communicated: written, spoken, done. The idea is like grass. It craves light, likes crowds, thrives on crossbreeding, grows better for being stepped on.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "To make a thief, make an owner; to create crime, create laws.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "Coercion is the least efficient means of obtaining order.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "The politician and the physicist both deal with things as they are, with real forces, the basic laws of the world.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "The law of evolution is that the strongest survives. Yes, and the strongest, in the existence of any social species, are those who are most social. In human terms, most ethical.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "Our model of the cosmos must be as inexhaustible as the cosmos. A complexity that includes not only duration but creation, not only being but becoming, not only geometry but ethics. It is not the answer we are after, but only how to ask the question.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "It was easy to share when there was enough, even barely enough, to go round. But when there was not enough? Then force entered in; might making right; power, and its tool, violence, and its most devoted ally, the averted eye.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "Existence is its own justification, need is right.", Author = "Ursula K. Le Guin" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ursula_K._Le_Guin", Text = "The individual cannot bargain with the State. The State recognizes no coinage but power: and it issues the coins itself.", Author = "Ursula K. Le Guin" },
